    color = pic[x][y]
    neighbors = [(x-1, y), (x+1, y), (x, y-1), (x, y+1)]
    for nx, ny in neighbors:
        if pic[nx][ny] == color:
            return False
    return True

def apply_recolor(pic, x, y):
