    for i in range(n):
        for j in range(m):
            new_pic[i][j] = pic[i][j]

def find_initial_picture_and_operations(n, m, k, pictures):
    from collections import defaultdict

    # Create a graph where each picture points to the pictures it can transition to
    transitions = defaultdict(list)

    for i in range(k + 1):
        for j in range(k + 1):
